SET search_path TO gabriel;

COMMENT ON TABLE inep_2023_categorias IS 'Significado de todos os códigos usados no banco (ex.: variavel TP_SEXO, codigo F = Feminino). Fonte: dicionários oficiais do INEP (ENADE 2023 e Censo da Educação Superior 2023). As views _desc já trazem esse texto pronto ao lado de cada código.';
COMMENT ON COLUMN inep_2023_categorias.variavel IS 'Nome da variável no dicionário do INEP (ex.: TP_SEXO, QE_I08) — parte da chave primária.';
COMMENT ON COLUMN inep_2023_categorias.codigo IS 'Código como aparece nos dados (ex.: F, 555, A) — parte da chave primária.';
COMMENT ON COLUMN inep_2023_categorias.descricao IS 'Significado do código, conforme o dicionário oficial do INEP.';

COMMENT ON TABLE inep_censo_2023_ies IS 'Cadastro das Instituições de Ensino Superior (IES), 1 linha por IES. Fonte: Censo da Educação Superior 2023 (MICRODADOS_ED_SUP_IES_2023.CSV).';
COMMENT ON COLUMN inep_censo_2023_ies.co_ies IS 'Código da IES (e-MEC) — chave primária';
COMMENT ON COLUMN inep_censo_2023_ies.nu_ano_censo IS 'Ano de referência do Censo da Educação Superior';
COMMENT ON COLUMN inep_censo_2023_ies.no_ies IS 'Nome da IES';
COMMENT ON COLUMN inep_censo_2023_ies.sg_ies IS 'Sigla da IES';
COMMENT ON COLUMN inep_censo_2023_ies.tp_organizacao_academica IS 'Tipo de Organização Acadêmica da IES | Códigos: 1 = Universidade; 2 = Centro Universitário; 3 = Faculdade; 4 = Instituto Federal de Educação, Ciência e Tecnologia; 5 = Centro Federal de Educação Tecnológica';
COMMENT ON COLUMN inep_censo_2023_ies.tp_categoria_administrativa IS 'Tipo de Categoria Administrativa da IES | Códigos: 1 = Pública Federal; 2 = Pública Estadual; 3 = Pública Municipal; 4 = Privada com fins lucrativos; 5 = Privada sem fins lucrativos; 6 = Privada - Particular em sentido estrito; 7 = Especial; 8 = Privada comunitária; 9 = Privada confessional';
COMMENT ON COLUMN inep_censo_2023_ies.no_mantenedora IS 'Nome da mantenedora da IES';
COMMENT ON COLUMN inep_censo_2023_ies.co_mantenedora IS 'Código único de identificação da mantenedora da IES';
COMMENT ON COLUMN inep_censo_2023_ies.no_regiao_ies IS 'Nome da região geográfica da sede administrativa ou reitoria da IES';
COMMENT ON COLUMN inep_censo_2023_ies.co_regiao_ies IS 'Código da região geográfica da sede administrativa ou reitoria da IES';
COMMENT ON COLUMN inep_censo_2023_ies.sg_uf_ies IS 'Sigla da Unidade da Federação da sede administrativa ou reitoria da IES';
COMMENT ON COLUMN inep_censo_2023_ies.no_uf_ies IS 'Nome da Unidade da Federação da sede administrativa ou reitoria da IES';
COMMENT ON COLUMN inep_censo_2023_ies.co_uf_ies IS 'Código da Unidade da Federação da sede administrativa ou reitoria da IES';
COMMENT ON COLUMN inep_censo_2023_ies.no_municipio_ies IS 'Nome do Município da sede administrativa ou reitoria da IES';
COMMENT ON COLUMN inep_censo_2023_ies.co_municipio_ies IS 'Código do Município da sede administrativa ou reitoria da IES';
COMMENT ON COLUMN inep_censo_2023_ies.in_capital_ies IS 'Informa se a sede administrativa ou reitoria da IES está localizada na capital da Unidade da Federação | Códigos: 0 = Não; 1 = Sim';

