COMMENT ON TABLE inep_enade_2023_aluno_avaliacao_curso IS 'Arquivo microdados2023_arq4: avaliação do estudante sobre o curso, questões QE_I27 a QE_I68 (1 = discordo totalmente ... 6 = concordo totalmente, 7 = não sei, 8 = não se aplica). 1 linha por estudante. Atenção: a linha desta tabela NÃO é o mesmo estudante da mesma linha em outra tabela, porque o INEP ordena cada arquivo de um jeito diferente (LGPD). Para cruzar informações, agrupe por curso (nu_ano, co_curso).';
COMMENT ON COLUMN inep_enade_2023_aluno_avaliacao_curso.id_registro IS 'Número da linha no arquivo original do INEP (chave primária). Identifica a linha só dentro desta tabela: não liga com outras tabelas.';
COMMENT ON COLUMN inep_enade_2023_aluno_avaliacao_curso.nu_ano IS 'Ano de realização do exame — chave estrangeira (nu_ano + co_curso): liga com inep_enade_2023_cadastro_curso';
COMMENT ON COLUMN inep_enade_2023_aluno_avaliacao_curso.co_curso IS 'Código do curso no Enade — chave estrangeira (nu_ano + co_curso): liga com inep_enade_2023_cadastro_curso';
